<?php
declare(strict_types=1);
function admin_layout(string $title,string $body,string $active=''): void {
 $u=current_user();$nav=['/admin/'=>'概要'];if(allowed('content'))$nav+=['/admin/content/?type=vehicle'=>'在庫車','/admin/content/?type=story'=>'カーストーリー','/admin/content/?type=news'=>'お知らせ','/admin/content/?type=column'=>'コラム'];if(allowed('inquiry'))$nav['/admin/inquiries/']='問い合わせ';if(allowed('admin'))$nav+=['/admin/users/'=>'アカウント','/admin/settings/'=>'接続・SEO設定'];
 $notice=$_SESSION['flash']??'';unset($_SESSION['flash']);header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');
 echo '<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'.e($title).' | Twin Assist CMS</title><link rel="stylesheet" href="/cms-admin.css"></head><body class="cms-body"><a class="cms-skip" href="#cms-main">本文へ</a><aside class="cms-sidebar"><a class="cms-brand" href="/admin/">TWIN ASSIST<small>CONTENT MANAGEMENT</small></a><span class="cms-env">'.(option('env')==='development'?'開発環境':'管理画面').'</span><nav aria-label="管理メニュー">';
 foreach($nav as $url=>$label)echo '<a href="'.e($url).'"'.($active===$label?' aria-current="page"':'').'>'.e($label).'<span>↗</span></a>';
 echo '</nav><div class="cms-sidebar-foot"><a href="/" target="_blank" rel="noopener">サイトを確認 ↗</a><a href="/admin/password/">パスワード変更</a>'.($u?'<form action="/admin/logout/" method="post">'.csrf_field().'<button>ログアウト</button></form>':'').'</div></aside><div class="cms-workspace"><header class="cms-header"><span>YOUR CAR. YOUR STORY.</span><span>'.e($u['name']??'管理者ログイン').' '.($u?'<small>'.e(['admin'=>'管理者','editor'=>'編集者','support'=>'問い合わせ担当'][$u['role']]).'</small>':'').'</span></header><main id="cms-main"><div class="cms-page-heading"><span class="cms-eyebrow">TWIN ASSIST / CMS</span><h1>'.e($title).'</h1></div>'.($notice?'<div class="cms-flash" role="status">'.e($notice).'</div>':'').$body.'</main><footer class="cms-footer">Twin Assist CMS · 公開と下書きは別に管理されます。</footer></div><script src="/cms-admin.js" defer></script></body></html>';
}
function input_field(string $name,string $label,mixed $value='',string $type='text',bool $required=false,string $help=''): string {return '<label class="cms-field">'.e($label).($required?'<span class="cms-required">必須</span>':'').'<input name="'.e($name).'" type="'.e($type).'" value="'.e($value).'"'.($required?' required':'').($type==='number'?' min="0" step="1"':'').' maxlength="'.($name==='slug'?'160':'600').'">'.($help?'<small>'.e($help).'</small>':'').'</label>';}
function select_field(string $name,string $label,array $options,mixed $value): string {$s='<label class="cms-field">'.e($label).'<select name="'.e($name).'">';foreach($options as $v=>$l)$s.='<option value="'.e($v).'"'.((string)$v===(string)$value?' selected':'').'>'.e($l).'</option>';return $s.'</select></label>';}
function check_field(string $name,string $label,bool $checked): string {return '<label class="cms-check"><input type="checkbox" name="'.e($name).'" value="1"'.($checked?' checked':'').'><span>'.e($label).'</span></label>';}
function text_field(string $name,string $label,string $value,string $help='',int $rows=5): string {return '<label class="cms-field">'.e($label).'<textarea name="'.e($name).'" rows="'.$rows.'">'.e($value).'</textarea>'.($help?'<small>'.e($help).'</small>':'').'</label>';}
function content_editor(string $type,?array $row,array $d,string $error=''): string {
 $d=array_replace(default_content($type),$d);$tagPreview=implode(' / ',effective_tags($d,$type));$id=(int)($row['id']??0);$version=(int)($row['version']??0);$isVehicle=$type==='vehicle';
 $s='<div class="cms-editor-toolbar"><a href="/admin/content/?type='.e($type).'">← '.e(CONTENT_LABELS[$type]).'一覧</a>'.($id?'<a class="cms-button secondary" href="/admin/preview/?id='.$id.'" target="_blank" rel="noopener">下書きをプレビュー ↗</a>':'').'</div>'.($error?'<div class="cms-error" role="alert">'.e($error).'</div>':'');
 $s.='<div class="cms-note">下書き保存では公開中の内容は変わりません。公開前に実車・事実・写真の権利と許諾を確認してください。'.(!enabled('indexing_enabled')?' この環境は検索エンジンへの公開が停止されています。':'').'</div>';
 $s.='<form method="post" class="cms-edit-form" id="content-form">'.csrf_field().'<input type="hidden" name="version" value="'.$version.'"><input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="type" value="'.e($type).'">';
 $s.='<section class="cms-panel"><h2>基本情報</h2><div class="cms-field-grid">'.input_field('title',$isVehicle?'掲載タイトル':'タイトル',$d['title'],'text',true).input_field('slug','URL末尾',$d['slug'],'text',true,'半角英小文字・数字・ハイフン。公開履歴がある場合は変更できません。').'</div>';
 if($isVehicle){$s.='<div class="cms-field-grid">'.select_field('category','カテゴリ',['kei'=>'軽自動車','commercial'=>'商用車・トラック','passenger'=>'乗用車'],$d['category']).select_field('sale_status','販売状態',['available'=>'販売中','negotiating'=>'商談中','sold'=>'売約済み'],$d['sale_status']).input_field('maker','メーカー',$d['maker']).input_field('model','車名',$d['model']).input_field('grade','グレード',$d['grade']).input_field('color','ボディカラー',$d['color']).input_field('year','年式（西暦）',$d['year'],'number').input_field('km','走行距離（km）',$d['km'],'number').input_field('inspection','車検情報',$d['inspection']).select_field('repair_history','修復歴',['unknown'=>'未確認','none'=>'なし','yes'=>'あり'],$d['repair_history']).input_field('transmission','ミッション',$d['transmission']).'</div>'.check_field('featured','トップページにおすすめ掲載する',(bool)$d['featured']);}
 else $s.='<div class="cms-field-grid">'.input_field('category','カテゴリ名',$d['category']).input_field('author','著者・担当者（任意）',$d['author']).'</div>'.input_field('related_ids','関連記事ID（カンマ区切り）',implode(',',$d['related_ids']),'text',false,'公開中の記事だけが公開ページに表示されます。');
 $s.=text_field('summary','紹介文',$d['summary'],'一覧カードなどに使用します。',3).'</section>';
 if($isVehicle){$s.='<section class="cms-panel"><h2>価格・装備</h2><div class="cms-field-grid">'.input_field('body_price','車両本体価格（税込・円）',$d['body_price'],'number').input_field('fees','諸費用（円）',$d['fees'],'number').input_field('total','支払総額（円）',$d['total'],'number').'</div>'.text_field('price_condition','支払総額の適用条件',$d['price_condition'],'登録地域・登録時期・納車方法、別途必要な任意費用等。購入に必須の費用を任意費用扱いにしないでください。',3).'<h3>装備マーク</h3><p class="cms-help">装備あり＝カラー、装備なし＝白黒。未確認は公開ページに表示しません。実車で確認し、あり・なしを選択してください。</p><div class="cms-equipment-checks">';foreach(EQUIPMENT_GROUPS as $group=>$options){$s.='<details class="cms-equipment-group" open><summary>'.e($group).' <small>'.count($options).'項目</small></summary><div class="cms-field-grid">';foreach($options as $key=>$label){$value=$d['equipment'][$key]??null;$s.=select_field('equipment['.$key.']',$label,[''=>'未確認','1'=>'装備あり','0'=>'装備なし'],$value===null?'':($value?'1':'0'));}$s.='</div></details>';}$s.='</div></section>';}
 $s.='<section class="cms-panel"><h2>本文・説明</h2>'.text_field('body','本文',$d['body'],'## 見出し、### 小見出し、- 箇条書き、[リンクの文字](/buy/) が使えます。HTMLは実行されず文字として表示されます。',16).'</section>';
 $s.='<section class="cms-panel"><h2>掲載画像</h2><p class="cms-help">画像を選び、上下ボタンで掲載順を調整できます。先頭が一覧の写真です。20枚まで。新しい画像はページ下部から登録できます。</p><input type="hidden" name="media_ids" id="media-ids" value="'.e(implode(',',$d['media_ids'])).'"><div id="chosen-media" class="cms-chosen-media"></div><div class="cms-media-library">';
 $images=query('SELECT * FROM media ORDER BY id DESC LIMIT 100')->fetchAll();$found=array_column($images,'id');foreach($d['media_ids'] as $mediaId)if(!in_array($mediaId,$found)){$im=query('SELECT * FROM media WHERE id=?',[$mediaId])->fetch();if($im)$images[]=$im;}
 foreach($images as $image)$s.='<label class="cms-media-option"><img src="/media/'.(int)$image['id'].'/" alt="'.e($image['alt']).'" loading="lazy"><span><input type="checkbox" data-media-id="'.(int)$image['id'].'" data-media-label="'.e($image['alt']).'"'.(in_array((int)$image['id'],$d['media_ids'],true)?' checked':'').'> #'.(int)$image['id'].' '.e($image['alt']).'</span></label>';
 $s.='</div></section><section class="cms-panel"><h2>検索・公開設定</h2>'.input_field('seo_title','SEOタイトル（未設定時は掲載タイトル）',$d['seo_title']).text_field('description','検索結果用の説明文',$d['description'],'内容を簡潔に説明してください。公開時に必要です。',3).input_field('tags','キーワードタグ（カンマ区切り・24件まで）',implode(', ',$d['tags']),'text',false,'内容に関係する語だけを指定します。地域名は所在地の確定情報ではありません。').select_field('target_region','地域の情報対象',[''=>'地域指定なし','taisho'=>'大正・大正区（この地域の方向け）'],$d['target_region']).check_field('auto_tags','タイトル・本文・カテゴリから関連するタグを自動で補う',(bool)$d['auto_tags']).'<p class="cms-help">保存・公開時の最新本文からタグを計算します。すべての記事へ全キーワードを一括挿入する処理ではありません。</p><p class="cms-note">現在のタグ候補：'.e($tagPreview?:'タイトル・本文を入力し、保存して確認してください。').'</p>'.text_field('answer_summary','この記事・車両の要点',$d['answer_summary'],'冒頭に表示する簡潔な結論。確認できた事実だけを記載します。',3).text_field('key_points','確認ポイント（1行1件・5件まで）',$d['key_points'],'本文と一致する要点を記入してください。',4).text_field('faq_text','よくある質問（1行につき 質問 | 回答・8件まで）',$d['faq_text'],'入力したQ&Aだけを本文と構造化データへ反映します。自動で回答を捏造しません。',5).text_field('sources_text','参考資料（1行につき 資料名 | https://URL・10件まで）',$d['sources_text'],'実際に内容確認した資料だけを記載します。',4).input_field('reviewed_on','内容を確認した日（任意）',$d['reviewed_on'],'date').check_field('indexable','本番公開時に検索対象へ含める',(bool)$d['indexable']).check_field('is_sample','サンプル・架空の内容（検索対象から除外）',(bool)$d['is_sample']).check_field('consent_checked','実際の内容・写真の権利・掲載許諾、または明示されたサンプルであることを確認しました',(bool)$d['consent_checked']).'<p class="cms-help">検索対象の指定だけでGoogleへの登録は保証されません。開発環境・下書き・サンプルはサイトマップへ載りません。</p></section><div class="cms-save-bar"><button name="action" value="save" class="cms-button secondary">下書き保存</button><button name="action" value="publish" class="cms-button" data-confirm="入力内容を公開ページへ反映します。よろしいですか？">'.($row&&$row['published']?'変更を公開':'公開する').'</button></div></form>';
 $s.='<section class="cms-panel" id="upload-panel"><h2>新しい画像を登録</h2><p class="cms-help">JPEG・PNG・WebP／8MB以下／各辺6000px・2000万画素以下。アップロード後に上の一覧へ追加されます。保存前の本文はそのまま残ります。</p><form action="/admin/media/" method="post" enctype="multipart/form-data" id="media-upload-form">'.csrf_field().'<label class="cms-field">写真<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label>'.input_field('alt','写真の説明（例：右前から見た外装）','','text',true).'<button class="cms-button secondary">画像を登録</button><p id="upload-result" role="status"></p></form></section>';
 return $s;
}
function route_admin(string $path): void {
 header('Cache-Control: no-store, private');header('X-Robots-Tag: noindex, nofollow');
 if($path==='/admin/login/'){
  if(current_user())redirect('/admin/');$error='';
  if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$ip=$_SERVER['REMOTE_ADDR']??'';$okIp=rate_allowed('login-ip',$ip,30,900);$okEmail=rate_allowed('login-account',$email,8,900);
   if(!$okIp||!$okEmail){http_response_code(429);$error='試行回数が多いため、15分ほど待ってからお試しください。';}else{$u=query('SELECT * FROM users WHERE email=? AND active=1',[$email])->fetch();$hash=$u['password_hash']??'$2y$10$H0P4hp65GPAzQdKjSsf4B.e9AcS60EItqP7yv8Scj/.eSBxTOs7dO';if(strlen($password)<=72&&password_verify($password,$hash)&&$u){session_regenerate_id(true);$_SESSION=['uid'=>(int)$u['id'],'signed_in'=>time(),'last_activity'=>time(),'password_stamp'=>hash_hmac('sha256',$hash,secret_key()),'csrf'=>bin2hex(random_bytes(32))];query('DELETE FROM rate_limits WHERE bucket=?',[hash_hmac('sha256','login-account|'.$email,secret_key())]);redirect('/admin/');}$error='メールアドレスまたはパスワードをご確認ください。';}
  }
  admin_layout('管理画面にログイン',($error?'<div class="cms-error" role="alert">'.e($error).'</div>':'').'<section class="cms-panel cms-login"><p>管理者から発行された個別アカウントを使用してください。</p><form method="post">'.csrf_field().input_field('email','メールアドレス','','email',true).'<label class="cms-field">パスワード<input type="password" name="password" autocomplete="current-password" required maxlength="200"></label><button class="cms-button">ログインする →</button></form><p class="cms-help">初期アカウントはサーバーのCLIで作成します。固定の初期パスワード・公開セットアップ画面はありません。</p></section>');return;
 }
 if(!current_user())redirect('/admin/login/');
 if($_SERVER['REQUEST_METHOD']==='POST')verify_csrf();
 if($path==='/admin/logout/'){if($_SERVER['REQUEST_METHOD']!=='POST')abort_request(405,'ログアウトは操作ボタンから行ってください。');$_SESSION=[];session_destroy();redirect('/admin/login/');}
 if($path==='/admin/'){
  $body='<div class="cms-note">'.(enabled('indexing_enabled')?'検索対象ページを本番サイトマップへ反映します。':'開発中：検索エンジンへの公開は停止中です。').(enabled('inquiries_enabled')?' 問い合わせ受付は有効です。':' 問い合わせ受付・メール通知の本番設定は未完了です。').'</div><div class="cms-stat-grid">';
  if(allowed('content'))foreach(CONTENT_LABELS as $type=>$label){$rows=query('SELECT SUM(published IS NOT NULL) AS live,COUNT(*) AS total FROM contents WHERE type=? AND deleted_at IS NULL',[$type])->fetch();$body.='<a class="cms-stat" href="/admin/content/?type='.$type.'"><span>'.e($label).'</span><strong>'.(int)$rows['total'].'<small>件</small></strong><p>公開中 '.(int)$rows['live'].'件</p><span class="cms-stat-arrow">↗</span></a>';}
  if(allowed('inquiry')){$count=(int)query("SELECT COUNT(*) FROM inquiries WHERE status='new'")->fetchColumn();$body.='<a class="cms-stat" href="/admin/inquiries/"><span>未対応のお問い合わせ</span><strong>'.$count.'<small>件</small></strong><p>受付一覧を確認する</p><span class="cms-stat-arrow">↗</span></a>';}
  $body.='</div><section class="cms-panel"><h2>運用の流れ</h2><ol class="cms-steps"><li><strong>入力・画像登録</strong><p>確認できた内容を登録します。</p></li><li><strong>下書き・プレビュー</strong><p>公開前に写真・価格・本文を確認します。</p></li><li><strong>明示的に公開</strong><p>公開した内容だけがサイトへ反映されます。</p></li></ol></section>';
  admin_layout('ダッシュボード',$body,'概要');return;
 }
 if($path==='/admin/content/'){
  require_ability('content');$type=(string)($_GET['type']??'vehicle');if(!isset(CONTENT_LABELS[$type]))abort_request(404,'種類が見つかりません。');$trash=isset($_GET['trash']);$keyword=trim((string)($_GET['q']??''));$sql='SELECT * FROM contents WHERE type=? AND deleted_at IS '.($trash?'NOT NULL':'NULL');$params=[$type];if($keyword!==''){$sql.=' AND title LIKE ?';$params[]='%'.$keyword.'%';}$rows=query($sql.' ORDER BY updated_at DESC,id DESC LIMIT 200',$params)->fetchAll();
  $body='<div class="cms-editor-toolbar"><form class="cms-search"><input type="hidden" name="type" value="'.e($type).'"><input name="q" aria-label="タイトルを検索" placeholder="タイトルで検索" value="'.e($keyword).'"><button class="cms-button secondary">検索</button></form><a class="cms-button" href="/admin/edit/?type='.e($type).'">＋ 新規登録</a></div><div class="cms-list-tabs"><a href="/admin/content/?type='.e($type).'">通常一覧</a><a href="/admin/content/?type='.e($type).'&amp;trash=1">ごみ箱</a></div><div class="cms-table-wrap"><table class="cms-table"><thead><tr><th>タイトル</th><th>公開状態</th><th>更新日時</th><th>操作</th></tr></thead><tbody>';
  foreach($rows as $r){$state=$r['published']?'公開中':'下書き';$body.='<tr><td><strong>'.e($r['title']).'</strong><small>#'.(int)$r['id'].' / '.e($r['slug']).'</small></td><td><span class="cms-badge'.($r['published']?' live':'').'">'.$state.'</span>'.($r['published']&&$r['draft']!==$r['published']?'<small>未公開の変更あり</small>':'').'</td><td>'.e(datetime_jp($r['updated_at'])).'</td><td>'.(!$trash?'<a href="/admin/edit/?id='.(int)$r['id'].'">編集 →</a>':'<form action="/admin/action/" method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$r['id'].'"><input type="hidden" name="version" value="'.(int)$r['version'].'"><button name="action" value="restore">復元する</button></form>').'</td></tr>';}
  if(!$rows)$body.='<tr><td colspan="4">まだ登録はありません。新規登録から始めましょう。</td></tr>';$body.='</tbody></table></div><p class="cms-help">最大200件を表示しています。検索で絞り込めます。</p>';admin_layout(CONTENT_LABELS[$type].'管理',$body,CONTENT_LABELS[$type]);return;
 }
 if($path==='/admin/edit/'){
  require_ability('content');$id=(int)($_GET['id']??0);$row=$id?query('SELECT * FROM contents WHERE id=? AND deleted_at IS NULL',[$id])->fetch():null;if($id&&!$row)abort_request(404,'編集対象が見つかりません。');$type=$row['type']??(string)($_GET['type']??'vehicle');if(!isset(CONTENT_LABELS[$type]))abort_request(404,'種類が見つかりません。');$d=$row?payload($row,true):default_content($type);$error='';
  if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=(string)($_POST['action']??'save');if(!in_array($action,['save','publish'],true))throw new InvalidArgumentException('操作を確認してください。');$newId=save_content($type,$row,$action);flash($action==='publish'?'公開ページへ反映しました。':'下書きを保存しました。公開中の内容は変更していません。');redirect('/admin/edit/?id='.$newId);}catch(InvalidArgumentException $e){$error=$e->getMessage();try{$d=posted_content($type);}catch(Throwable){}}}
  $body=content_editor($type,$row,$d,$error);
  if($row)$body.='<section class="cms-panel cms-danger"><h2>公開停止・削除</h2><form action="/admin/action/" method="post">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$row['id'].'"><input type="hidden" name="version" value="'.(int)$row['version'].'">'.($row['published']?'<a class="cms-button secondary" href="'.e(content_url($row)).'" target="_blank" rel="noopener">公開ページを見る ↗</a> <button class="cms-button warning" name="action" value="unpublish" data-confirm="公開を停止します。よろしいですか？">公開を停止する</button>':'<button class="cms-button warning" name="action" value="trash" data-confirm="ごみ箱に移動します。よろしいですか？">ごみ箱へ移動</button>').'</form></section>';
  admin_layout(CONTENT_LABELS[$type].($row?'を編集':'を新規登録'),$body,CONTENT_LABELS[$type]);return;
 }
 if($path==='/admin/action/'){
  require_ability('content');if($_SERVER['REQUEST_METHOD']!=='POST')abort_request(405,'操作ボタンから実行してください。');$row=query('SELECT * FROM contents WHERE id=?',[(int)($_POST['id']??0)])->fetch();if(!$row)abort_request(404,'対象が見つかりません。');try{content_action($row,(string)($_POST['action']??''));flash('公開状態を更新しました。');}catch(InvalidArgumentException $e){flash($e->getMessage());}redirect('/admin/content/?type='.$row['type']);
 }
 if($path==='/admin/media/'){
  require_ability('content');if($_SERVER['REQUEST_METHOD']!=='POST')abort_request(405,'画像は登録フォームからアップロードしてください。');header('Content-Type: application/json; charset=UTF-8');try{$id=upload_media();$image=query('SELECT id,alt FROM media WHERE id=?',[$id])->fetch();echo json_data(['ok'=>true,'media'=>$image]);}catch(InvalidArgumentException $e){http_response_code(422);echo json_data(['ok'=>false,'error'=>$e->getMessage()]);}return;
 }
 if($path==='/admin/preview/'){
  require_ability('content');$row=query('SELECT * FROM contents WHERE id=? AND deleted_at IS NULL',[(int)($_GET['id']??0)])->fetch();if(!$row)abort_request(404,'プレビューが見つかりません。');render_content($row,true);return;
 }
 if($path==='/admin/inquiries/'){require_ability('inquiry');admin_inquiries();return;}
 if($path==='/admin/inquiry-delete/'){
  require_ability('admin');if($_SERVER['REQUEST_METHOD']!=='POST'||($_POST['confirm_delete']??'')!=='yes')abort_request(422,'削除の確認が必要です。');
  $id=(int)($_POST['id']??0);db()->beginTransaction();try{$r=query('SELECT id,status,version FROM inquiries WHERE id=? FOR UPDATE',[$id])->fetch();if(!$r||$r['status']!=='closed'||(int)$r['version']!==(int)($_POST['version']??0))throw new InvalidArgumentException('完了した問い合わせの最新内容を確認してください。');query('DELETE FROM inquiries WHERE id=?',[$id]);audit('erase_personal_data','inquiry',$id);db()->commit();flash('問い合わせの個人情報と通知記録を完全削除しました。');redirect('/admin/inquiries/');}catch(InvalidArgumentException $e){db()->rollBack();flash($e->getMessage());redirect('/admin/inquiries/');}
 }
 if($path==='/admin/users/'){require_ability('admin');admin_users();return;}
 if($path==='/admin/password/'){
  $error='';if($_SERVER['REQUEST_METHOD']==='POST'){
   $hash=query('SELECT password_hash FROM users WHERE id=?',[current_user()['id']])->fetchColumn();$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');
   if(!rate_allowed('change-password',(string)current_user()['id'],8,900))$error='試行回数が多すぎます。時間をおいてください。';elseif(strlen($old)>72||!password_verify($old,$hash))$error='現在のパスワードを確認してください。';elseif(strlen($new)<14||strlen($new)>72||$new!==(string)($_POST['repeat_password']??''))$error='新しいパスワードは14〜72バイトで、確認欄も一致させてください。';else{$newHash=password_hash($new,PASSWORD_DEFAULT);query('UPDATE users SET password_hash=? WHERE id=?',[$newHash,current_user()['id']]);audit('change_password','user',(int)current_user()['id']);session_regenerate_id(true);$_SESSION['password_stamp']=hash_hmac('sha256',$newHash,secret_key());flash('パスワードを更新しました。');redirect('/admin/');}}
  $body=($error?'<div class="cms-error">'.e($error).'</div>':'').'<section class="cms-panel"><form method="post">'.csrf_field();foreach(['old_password'=>'現在のパスワード','new_password'=>'新しいパスワード','repeat_password'=>'新しいパスワード（確認）'] as $name=>$label)$body.='<label class="cms-field">'.$label.'<input name="'.$name.'" type="password" required maxlength="72" autocomplete="'.($name==='old_password'?'current-password':'new-password').'"></label>';$body.='<button class="cms-button">パスワードを更新</button></form></section>';admin_layout('パスワード変更',$body);return;
 }
 if($path==='/admin/settings/'){
  require_ability('admin');$body='<section class="cms-panel"><h2>接続・公開状態</h2><dl class="cms-status-list">';foreach(['サイトURL'=>base_url(),'検索対象の本番公開'=>enabled('indexing_enabled')?'有効':'停止中（全体noindex）','問い合わせ受付'=>enabled('inquiries_enabled')?'有効':'停止中（確認まで）','メール通知'=>enabled('mail_enabled')?'送信処理の設定あり（配達は別途確認）':'未設定・停止中'] as $label=>$value)$body.='<div><dt>'.e($label).'</dt><dd>'.e($value).'</dd></div>';$body.='</dl><p class="cms-help">秘密値・接続先は公開画面から編集せず、サーバーの非公開設定で管理します。本番ドメイン・HTTPS・受付先・個人情報の運用を確定してから有効化します。</p><a class="cms-button secondary" href="/sitemap.xml" target="_blank" rel="noopener">サイトマップを確認 ↗</a></section>';admin_layout('接続・SEO設定',$body,'接続・SEO設定');return;
 }
 abort_request(404,'管理ページが見つかりません。');
}
function admin_inquiries(): void {
 $id=(int)($_GET['id']??0);$error='';
 if($id){$r=query('SELECT i.*,n.state AS notification_state,n.last_error FROM inquiries i LEFT JOIN notifications n ON n.inquiry_id=i.id WHERE i.id=?',[$id])->fetch();if(!$r)abort_request(404,'問い合わせが見つかりません。');
  if($_SERVER['REQUEST_METHOD']==='POST'){
   $status=(string)($_POST['status']??'');$note=trim((string)($_POST['note']??''));$assignee=(int)($_POST['assigned_to']??0);
   if(!in_array($status,['new','in_progress','closed'],true)||strlen($note)>15000)$error='対応状況・メモを確認してください。';elseif($assignee&&!query("SELECT id FROM users WHERE id=? AND active=1 AND role IN('admin','support')",[$assignee])->fetch())$error='担当者を確認してください。';else{db()->beginTransaction();try{$updated=query('UPDATE inquiries SET status=?,note=?,assigned_to=?,updated_at=UTC_TIMESTAMP(),version=version+1 WHERE id=? AND version=?',[$status,$note,$assignee?:null,$id,(int)($_POST['version']??0)]);if(!$updated->rowCount())throw new InvalidArgumentException('他の担当者が更新しています。再読み込みしてください。');audit('update_status','inquiry',$id);db()->commit();flash('対応状況を更新しました。');redirect('/admin/inquiries/?id='.$id);}catch(InvalidArgumentException $e){db()->rollBack();$error=$e->getMessage();}}}
  $body='<a href="/admin/inquiries/">← 一覧へ</a>'.($error?'<div class="cms-error">'.e($error).'</div>':'').'<section class="cms-panel"><h2>受付 #'.$id.'</h2><dl class="cms-status-list">';foreach(['受付日時'=>datetime_jp($r['created_at']),'相談の種類'=>INQUIRY_LABELS[$r['type']]??$r['type'],'お名前'=>$r['name'],'メール'=>$r['email'],'電話'=>$r['phone'],'対象車両'=>$r['vehicle_title'],'ご相談内容'=>$r['message'],'同意文書版'=>$r['consent_version'],'通知処理'=>$r['notification_state'].'（acceptedは送信処理受付。配達保証ではありません）'] as $label=>$value)$body.='<div><dt>'.e($label).'</dt><dd>'.nl2br(e($value)).'</dd></div>';$body.='</dl></section><section class="cms-panel"><h2>社内の対応管理</h2><form method="post">'.csrf_field().'<input type="hidden" name="version" value="'.(int)$r['version'].'">'.select_field('status','対応状況',['new'=>'未対応','in_progress'=>'対応中','closed'=>'完了'],$r['status']);$users=[0=>'未割当'];foreach(query("SELECT id,name FROM users WHERE active=1 AND role IN('admin','support') ORDER BY name")->fetchAll() as $u)$users[$u['id']]=$u['name'];$body.=select_field('assigned_to','担当者',$users,$r['assigned_to']??0).text_field('note','社内メモ',$r['note'],'公開ページには出ません。必要最小限の内容を記録してください。').'<button class="cms-button">対応状況を保存</button></form></section>';if(allowed('admin')&&$r['status']==='closed')$body.='<section class="cms-panel cms-danger"><h2>保存期間経過後の完全削除</h2><p class="cms-help">通知記録を含め完全削除し、元に戻せません。法定保存・対応上の必要性と社内の保存期間を確認して実行してください。バックアップ内の保存・削除も別途管理してください。</p><form method="post" action="/admin/inquiry-delete/">'.csrf_field().'<input type="hidden" name="id" value="'.$id.'"><input type="hidden" name="version" value="'.(int)$r['version'].'"><label class="cms-check"><input type="checkbox" name="confirm_delete" value="yes" required><span>保存の必要がないことと、完全削除を確認しました</span></label><button class="cms-button warning" data-confirm="個人情報を完全削除します。元に戻せません。よろしいですか？">問い合わせを完全削除する</button></form></section>';admin_layout('問い合わせの詳細',$body,'問い合わせ');return;
 }
 $status=(string)($_GET['status']??'');$params=[];$where='';if(in_array($status,['new','in_progress','closed'],true)){$where=' WHERE i.status=?';$params[]=$status;}$rows=query('SELECT i.*,n.state AS notification_state FROM inquiries i LEFT JOIN notifications n ON n.inquiry_id=i.id'.$where.' ORDER BY i.id DESC LIMIT 200',$params)->fetchAll();
 $body='<div class="cms-note">個人情報を含む画面です。記事へ転記せず、保存期間・削除運用は本番受付前に確定してください。通知設定が未完了でも、受付データはこの一覧から確認できます。</div><div class="cms-list-tabs"><a href="/admin/inquiries/">すべて</a><a href="?status=new">未対応</a><a href="?status=in_progress">対応中</a><a href="?status=closed">完了</a></div><div class="cms-table-wrap"><table class="cms-table"><thead><tr><th>受付</th><th>種別・お名前</th><th>対応</th><th>通知処理</th></tr></thead><tbody>';
 foreach($rows as $r)$body.='<tr><td><a href="?id='.(int)$r['id'].'">#'.(int)$r['id'].' 詳細 →</a><small>'.e(datetime_jp($r['created_at'])).'</small></td><td>'.e(INQUIRY_LABELS[$r['type']]??$r['type']).'<small>'.e($r['name']).'</small></td><td>'.e(['new'=>'未対応','in_progress'=>'対応中','closed'=>'完了'][$r['status']]).'</td><td>'.e($r['notification_state']).'</td></tr>';
 if(!$rows)$body.='<tr><td colspan="4">まだ問い合わせはありません。</td></tr>';$body.='</tbody></table></div>';admin_layout('問い合わせ管理',$body,'問い合わせ');
}
function admin_users(): void {
 $error='';if($_SERVER['REQUEST_METHOD']==='POST'){
  $id=(int)($_POST['id']??0);$role=(string)($_POST['role']??'editor');$active=isset($_POST['active'])?1:0;
  try{
   if(!in_array($role,['admin','editor','support'],true))throw new InvalidArgumentException('役割を確認してください。');
   if($id){if($id===(int)current_user()['id']&&($role!=='admin'||!$active))throw new InvalidArgumentException('自分自身の管理者権限・有効状態は解除できません。');query('UPDATE users SET role=?,active=? WHERE id=?',[$role,$active,$id]);audit('update_access','user',$id);}
   else{$email=strtolower(trim((string)($_POST['email']??'')));$name=trim((string)($_POST['name']??''));$password=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190||$name===''||text_length($name)>100||strlen($password)<14||strlen($password)>72)throw new InvalidArgumentException('有効なメール・お名前と、14〜72バイトのパスワードを入力してください。');query('INSERT INTO users(email,name,password_hash,role) VALUES(?,?,?,?)',[$email,$name,password_hash($password,PASSWORD_DEFAULT),$role]);audit('create_user','user',(int)db()->lastInsertId());}
   flash('アカウントを更新しました。');redirect('/admin/users/');
  }catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$error='そのメールアドレスは既に登録されています。';}
 }
 $body=($error?'<div class="cms-error">'.e($error).'</div>':'').'<section class="cms-panel"><h2>アカウント一覧</h2><p class="cms-help">編集者は問い合わせの個人情報を閲覧できません。問い合わせ担当は公開記事を変更できません。</p>';
 foreach(query('SELECT id,email,name,role,active FROM users ORDER BY id')->fetchAll() as $u)$body.='<form method="post" class="cms-user-row">'.csrf_field().'<input type="hidden" name="id" value="'.(int)$u['id'].'"><div><strong>'.e($u['name']).'</strong><small>'.e($u['email']).'</small></div>'.select_field('role','役割',['admin'=>'管理者','editor'=>'編集者','support'=>'問い合わせ担当'],$u['role']).check_field('active','有効',(bool)$u['active']).'<button class="cms-button secondary">変更</button></form>';
 $body.='</section><section class="cms-panel"><h2>個別アカウントの追加</h2><form method="post">'.csrf_field().input_field('name','お名前','','text',true).input_field('email','メールアドレス','','email',true).'<label class="cms-field">初期パスワード（14〜72バイト）<input type="password" name="password" minlength="14" maxlength="72" required autocomplete="new-password"></label>'.select_field('role','役割',['editor'=>'編集者','support'=>'問い合わせ担当','admin'=>'管理者'],'editor').'<button class="cms-button">アカウントを作成</button></form></section>';admin_layout('アカウント管理',$body,'アカウント');
}
